class Solution {
public:
    int minFlips(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        int N = m * n;
        int target = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (mat[i][j])
                    target |= (1 << (i * n + j));

        int affect[9];
        int dr[] = {0, 0, 1, -1, 0};
        int dc[] = {1, -1, 0, 0, 0};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int mask = 0;
                for (int d = 0; d < 5; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n)
                        mask |= (1 << (ni * n + nj));
                }
                affect[i * n + j] = mask;
            }
        }

        int cur = 0, g = 0, flips = 0, best = -1;
        int total = 1 << N;
        for (int i = 0; i < total; i++) {
            if (cur == target) {
                if (best == -1 || flips < best)
                    best = flips;
            }
            if (i == total - 1) break;
            int bit = __builtin_ctz(i + 1);
            if ((g >> bit) & 1) flips--;
            else flips++;
            g ^= (1 << bit);
            cur ^= affect[bit];
        }
        return best;
    }
};
